config.script:
logger=system.util.getLogger('LoadMongoData')

def getConnectorState(name):
	allow=True
	for connector in self.session.custom.admin.mongoAccess:
		if name==connector['name']:
			allow=connector['allow']
			break
	return allow

self.custom.date=system.date.now()
connectorDrop=[]
try:
	connectors=system.mongodb.listConnectorInfo()

	for connector in connectors:
		if connector['status']=='Valid':
			if getConnectorState(connector['name']) and connector['name'] not in self.session.custom.admin.disabledMongoConnections:
				connectorDrop.append({
				  "value": connector['name'],
				  "label": connector['name']
				})
		else:
			logger.warn('MongoDB [{}] is Faulted, check that Database(s) and Collection(s) are configured in DB manager'.format(connector['name']))
except:
	pass		
self.getChild("root").getChild("Connectors").getChild("Connectors").props.options=connectorDrop
if len(connectorDrop)>0:
	firstCollection=connectorDrop[-1]['value']
	self.getChild("root").getChild("Connectors").getChild("Connectors").props.value=firstCollection

